export const getSaveAttemptAnswerUrl = (id: string, questionId: string) => {
  return `/practice/attempts/${id}/answers/${questionId}`;
};

/**
 * Send baseRevision = the revision you last saw. A stale revision returns 409 practice.revision_conflict with currentRevision. Refused while paused, after submission, and after a timed attempt's deadline plus 10 seconds.
 * @summary Autosave your answer to one question
 */
export const saveAttemptAnswer = async (
  id: string,
  questionId: string,
  saveAttemptAnswerRequest: SaveAttemptAnswerRequest,
  options?: Parameters<typeof apiFetch>[1],
): Promise<SavedAnswer> => {
  const getHeaders = (
    h?: NonNullable<RequestInit["headers"]>,
  ): Record<string, string | readonly string[]> => {
    if (!h) return {};
    if (h instanceof Headers) return Object.fromEntries(h.entries());
    if (Symbol.iterator in h) {
      return Object.fromEntries(
        Array.from(
          h as Iterable<Iterable<string>>,
          (entry) => Array.from(entry) as [string, string],
        ),
      );
    }
    const headers: Record<string, string | readonly string[]> = {};
    for (const [name, value] of Object.entries<
      string | readonly string[] | undefined
    >(h)) {
      if (value !== undefined) headers[name] = value;
    }
    return headers;
  };
  return apiFetch<SavedAnswer>(getSaveAttemptAnswerUrl(id, questionId), {
    ...options,
    method: "PUT",
    headers: {
      "Content-Type": "application/json",
      ...getHeaders(options?.headers),
    },
    body: JSON.stringify(saveAttemptAnswerRequest),
  });
};

